mapper.select:



        and s.book_id = #{bookId}


        and b.isbn = #{isbn}


        and b.title like concat('%', #{title}, '%')


        and s.location_id = #{locationId}


        and s.qty_available > 0


        and s.create_time >= #{params.beginTime}


        and s.create_time <= #{params.endTime}


order by s.book_id desc, s.location_id asc

select ifnull(sum(s.qty_available), 0) as qtyAvailable, ifnull(sum(s.qty_locked), 0) as qtyLocked, ifnull(sum(s.qty_borrowed), 0) as qtyBorrowed, ifnull(sum(s.qty_damaged), 0) as qtyDamaged, count(distinct s.book_id) as bookKind, ifnull(sum((s.qty_available + s.qty_locked + s.qty_borrowed + s.qty_damaged) * b.cost_price), 0) as totalAmount from biz_stock s left join biz_book b on b.book_id = s.book_id
and s.location_id = #{locationId}
and b.category_id = #{categoryId}

select b.category_id as categoryId, ifnull(c.category_name, '未分类') as categoryName, count(distinct s.book_id) as bookKind, ifnull(sum(s.qty_available + s.qty_locked + s.qty_borrowed + s.qty_damaged), 0) as totalQty, ifnull(sum((s.qty_available + s.qty_locked + s.qty_borrowed + s.qty_damaged) * b.cost_price), 0) as totalAmount from biz_stock s left join biz_book b on b.book_id = s.book_id left join biz_category c on c.category_id = b.category_id
and s.location_id = #{locationId}
group by b.category_id, c.category_name order by totalAmount desc, totalQty desc

mapper.update:
update biz_stock
set safety_qty = #{safetyQty}, update_time = now()
where book_id = #{bookId}
